CREATE SEQUENCE order_reference_seq START 1;
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference varchar(20) NOT NULL UNIQUE, customer_user_id uuid NOT NULL, business_id uuid NOT NULL, business_location_id uuid NOT NULL, offer_id uuid, status varchar(20) NOT NULL, currency char(3) NOT NULL DEFAULT 'EUR', quantity int NOT NULL, unit_price numeric(10,2) NOT NULL, original_unit_price numeric(10,2) NOT NULL, total_price numeric(10,2) NOT NULL, item_name varchar(120) NOT NULL, business_name varchar(120) NOT NULL, image_url text, pickup_start_at timestamptz NOT NULL, pickup_end_at timestamptz NOT NULL, pickup_code varchar(6) NOT NULL, canceled_at timestamptz, cancel_reason varchar(280), completed_at timestamptz, completed_by_user_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0,
 CONSTRAINT fk_order_customer FOREIGN KEY(customer_user_id) REFERENCES users(id), CONSTRAINT fk_order_business FOREIGN KEY(business_id) REFERENCES businesses(id), CONSTRAINT fk_order_location FOREIGN KEY(business_location_id,business_id) REFERENCES business_locations(id,business_id), CONSTRAINT fk_order_offer FOREIGN KEY(offer_id) REFERENCES offers(id) ON DELETE SET NULL, CONSTRAINT fk_order_completed_by FOREIGN KEY(completed_by_user_id) REFERENCES users(id),
 CONSTRAINT ck_order_status CHECK(status IN ('ACTIVE','COMPLETED','CANCELED')), CONSTRAINT ck_order_quantity CHECK(quantity>0), CONSTRAINT ck_order_money CHECK(unit_price>=0 AND original_unit_price>=unit_price AND total_price=unit_price*quantity), CONSTRAINT ck_order_code CHECK(length(pickup_code)=6), CONSTRAINT ck_order_pickup CHECK(pickup_end_at>pickup_start_at));
CREATE TABLE order_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL, from_status varchar(20), to_status varchar(20) NOT NULL, changed_by_user_id uuid, reason varchar(280), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fk_history_order FOREIGN KEY(order_id) REFERENCES orders(id), CONSTRAINT fk_history_user FOREIGN KEY(changed_by_user_id) REFERENCES users(id));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE, user_id uuid NOT NULL, method varchar(20) NOT NULL, status varchar(20) NOT NULL, amount numeric(10,2) NOT NULL, currency char(3) NOT NULL, provider varchar(40) NOT NULL, provider_reference varchar(120), idempotency_key varchar(100), failure_code varchar(60), captured_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fk_payment_order FOREIGN KEY(order_id) REFERENCES orders(id), CONSTRAINT fk_payment_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT ck_payment_amount CHECK(amount>=0));
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL, order_id uuid NOT NULL, amount numeric(10,2) NOT NULL, currency char(3) NOT NULL, status varchar(20) NOT NULL, reason varchar(280), provider_reference varchar(120), requested_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, failure_reason varchar(280), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fk_refund_payment FOREIGN KEY(payment_id) REFERENCES payments(id), CONSTRAINT fk_refund_order FOREIGN KEY(order_id) REFERENCES orders(id), CONSTRAINT ck_refund_amount CHECK(amount>=0));
CREATE TABLE idempotency_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, scope varchar(60) NOT NULL, key varchar(100) NOT NULL, request_hash char(64) NOT NULL, response_status int, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, CONSTRAINT fk_idempotency_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT uq_idempotency UNIQUE(user_id,scope,key));
